import { describe, expect, it } from '@jest/globals';
import hint from '../../../src/hints/technical/technical-html-size.js';
import { htmlPage } from '../../helpers/page.js';
import { runHint } from '../../helpers/run-hint.js';

describe('technical-html-size', () => {
  it('passes a small page', async () => {
    expect(await runHint(hint, htmlPage({}))).toEqual([]);
  });

  it('reports a large page', async () => {
    const problems = await runHint(
      hint,
      htmlPage({
        body: '<p></p>',
      }),
    );
    expect(problems).toHaveLength(1);
    expect(problems[0].message).toContain('KB');
  });
});
